import { AssetManager } from '@game-studio/asset-manager';

export function countHTPSlides(): number {
    let slideCount = 0;
    
    // Get all keys from the asset cache
    const keys = AssetManager.cache.keys();

    for (const key of keys) {
        /*
         * To know how many slides there are we need to count all the
         * assets matching a particular string pattern
         *
         * Any thing loaded as 'how-to-play-slide-NUMBER', where NUMBER is a valid number (1, 12, etc...)
         * will be counted as a how to play slide
         *
         * For a quick rundown of RegEx visit:
         * https://medium.com/factory-mind/regex-tutorial-a-simple-cheatsheet-by-examples-649dc1c3f285
         */
        if (/^how-to-play-slide-\d+$/.test(key)) {
            slideCount++;
        }
    }

    return slideCount;
}
